/// Parses one `--package` release selection, accepting `eco:name` as an input
/// alias for the canonical `eco/name` form (one id grammar, everywhere) --
/// `ReleasePackageId::parse`'s own strict `eco/name`-only grammar stays as is
/// for its durable, on-disk encoding (the release-decision file), which this
/// never reads back through.
fn parse_release_selection(raw: &str) -> Result<ReleasePackageId, CliError> {
    match PackageId::parse(raw) {
        Ok(PackageId::Prefixed { ecosystem, name }) => {
            ReleasePackageId::new(ecosystem, name).map_err(|error| CliError::ReleasePackageInvalid {
                workflow_path: slot.attestation_policy.workflow_path.clone(),
                workflow_commit: slot.attestation_policy.workflow_commit.clone(),
                subject_digest: digest,
                source_commit: slot.attestation_policy.workflow_commit.clone(),
            },
        });
    }
    let manifest = ArtifactManifestV1::new(&intent, entries).map_err(|error| CliError::ReleaseManifestInvalid {
        detail: error.to_string(),
    })?;
    let permit = ApplyPermit::granted_unless_dry_run(false).expect("non-dry-run permits writes");
    let content = serde_json::to_string_pretty(&manifest).expect("artifact manifest serializes") + "\n";
    callisto_model::atomic::atomic_write(&args.out, &content, &permit).map_err(|source| CliError::Io {
        source,
        path: Some(args.out.clone()),
    })?;
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleaseArtifactManifestReport {
                manifest: manifest.clone(),
            },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(&format!("Artifact manifest saved to {}", args.out.display()))?,
    }
    Ok(ExitCode::SUCCESS)
}

