//! Interface for typed managed release-pull-request decisions, and for
//! building the exact forge commit-API file changes the executor submits.
//! `decide` and `verify` are read-only; `commit-plan` reads the Git index
//! and worktree but writes no forge state itself -- the executor script is
//! the only thing that ever calls GitHub.

use std::process::ExitCode;

use callisto_graph::commands::{status, StatusOptions};
use callisto_model::vcs::GitAccess;
use callisto_model::{
    ApplyPermit, CommitSha, GitHubRepository, ReleasePrActionV2, ReleasePrCommitPlanReport, ReleasePrCommitPlanV1,
    ReleasePrConfigV1, ReleasePrDecideReport, ReleasePrDecisionError, ReleasePrDecisionV2, ReleasePrDecisionWireV2,
    ReleasePrSnapshotV2, ReleasePrSnapshotWireV2, ReleasePrVerifyReport,
};

use crate::cli::{
    GlobalArgs, OutputFormat, ReleasePrArgs, ReleasePrCommitPlanArgs, ReleasePrDecideArgs, ReleasePrVerifyArgs,
};
use crate::commands::read_json_arg;
use crate::error::CliError;
use crate::output::{emit_line, emit_report};
use crate::runner::CliCommandRunner;
use crate::workspace::load_workspace;

pub fn handle(args: ReleasePrArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    match args {
        ReleasePrArgs::Decide(args) => decide(args, global),
        ReleasePrArgs::Verify(args) => verify(args, global),
        ReleasePrArgs::CommitPlan(args) => commit_plan(args, global),
    }
}

/// Reads `flag`'s argument (file, inline JSON, or `-` for stdin) as an unvalidated wire
/// value. Kept separate from the domain type's own validating constructor so a JSON parse
/// failure (`E281`) and a domain validation failure (its own typed `E1xx` code) are never
/// folded into one generic error.
fn read_json_arg_as<T: serde::de::DeserializeOwned>(flag: &'static str, arg: &str) -> Result<T, CliError> {
    let text = read_json_arg(arg)?;
    serde_json::from_str(&text).map_err(|error| CliError::ReleasePrArgJsonInvalid {
        flag,
        detail: error.to_string(),
    })
}

fn verify(args: ReleasePrVerifyArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let decision_wire: ReleasePrDecisionWireV2 = read_json_arg_as("decision", &args.decision)?;
    let decision = ReleasePrDecisionV2::from_wire(decision_wire)?;
    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_arg_as("snapshot", &args.snapshot)?;
    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
    decision.verify_snapshot(&snapshot)?;
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleasePrVerifyReport { ok: true },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line("release PR decision still matches forge snapshot")?,
    }
    Ok(ExitCode::SUCCESS)
}

fn decide(args: ReleasePrDecideArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_arg_as("snapshot", &args.snapshot)?;
    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
    let repository =
        GitHubRepository::parse(&args.repository).map_err(|_error| ReleasePrDecisionError::InvalidRepository {
            repository: args.repository.clone(),
        })?;
    let config = ReleasePrConfigV1::new(repository, args.base_branch, args.release_branch)?;

    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let inference = crate::workspace::select_inference();
    let status = status(&workspace, &inference, &StatusOptions::default())?;
    let decision = ReleasePrDecisionV2::derive(status.has_changesets, &config, &snapshot)?;

    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleasePrDecideReport { decision },
            global.dry_run,
        )?,
        OutputFormat::Text => render_decision(&decision)?,
    }
    Ok(ExitCode::SUCCESS)
}

fn commit_plan(args: ReleasePrCommitPlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let base_commit = CommitSha::parse(&args.base_commit)?;

    let start = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
        source,
        path: Some(global.cwd.clone()),
    })?;
    let runner = CliCommandRunner;
    let git = GitAccess::new(&start, &runner);
    let changes = git.staged_changes_since(&base_commit)?;
    let plan = ReleasePrCommitPlanV1::from_changes(base_commit, args.message, changes)?;

    match args.out {
        Some(path) => {
            let permit =
                ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::ReleasePrCommitPlanDryRun)?;
            let content = serde_json::to_string_pretty(&plan).expect("commit plan serializes") + "\n";
            callisto_model::atomic::atomic_write(&path, &content, &permit).map_err(|source| CliError::Io {
                source,
                path: Some(path),
            })?;
        }
        None => emit_report(
            &mut std::io::stdout(),
            &ReleasePrCommitPlanReport { plan },
            global.dry_run,
        )?,
    }
    Ok(ExitCode::SUCCESS)
}

fn render_decision(decision: &ReleasePrDecisionV2) -> Result<(), CliError> {
    match &decision.action {
        ReleasePrActionV2::Noop { reason } => emit_line(&format!("release PR: no-op ({reason:?})"))?,
        ReleasePrActionV2::Create { branch, staging_branch } => {
            emit_line(&format!("release PR: create {branch} (staging {staging_branch})"))?
        }

use std::io::{self, Write};

use serde::Serialize;

use crate::cli::OutputFormat;

pub fn write_json<W: io::Write, S: Serialize + ?Sized>(w: &mut W, val: &S) -> io::Result<()> {
    let text = serde_json::to_string_pretty(val)?;
    writeln!(w, "{text}")
}

/// Serializes any `Report` value to the one JSON success envelope every
/// command shares: `{schemaVersion, command, dryRun, ...payload,
/// diagnostics}`. `command` comes from `R::COMMAND`, `schemaVersion` from
/// the payload's own `Report::schema_version()` (re-inserted at the top
/// level rather than left flattened, so it appears exactly once). Callers
/// pass their `Report` to this function instead of hand-building a JSON envelope.
pub fn emit_report<W: io::Write, R: callisto_model::Report>(w: &mut W, val: &R, dry_run: bool) -> io::Result<()> {
    let mut value = serde_json::to_value(val)?;
    if let serde_json::Value::Object(map) = &mut value {
        map.insert("schemaVersion".to_string(), serde_json::json!(val.schema_version()));
        map.insert("command".to_string(), serde_json::json!(R::COMMAND));
        map.insert("dryRun".to_string(), serde_json::json!(dry_run));
    }
    let text = serde_json::to_string_pretty(&value)?;
    writeln!(w, "{text}")
}

/// Writes `bytes` to stdout. A closed reading end (e.g. `callisto ... | head`)
/// is not a failure -- it's the normal way a consumer stops reading -- so a
/// `BrokenPipe` is swallowed here instead of propagating, which is what
/// makes this the one sink callers use in place of `println!` (which panics
/// on that same condition).
pub fn write_stdout(bytes: &[u8]) -> io::Result<()> {
    write_swallowing_broken_pipe(&mut io::stdout(), bytes)
}

/// The actual classification [`write_stdout`] applies, pulled out so a test
/// can exercise it against a real closed pipe without touching the
/// process's real (unredirectable, in-process) stdout fd.
fn write_swallowing_broken_pipe<W: Write>(w: &mut W, bytes: &[u8]) -> io::Result<()> {
    match w.write_all(bytes) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => Ok(()),
        Err(e) => Err(e),
    }
}

/// Writes one line (plus trailing newline) through [`write_stdout`].
pub fn emit_line(line: &str) -> io::Result<()> {
    write_stdout(format!("{line}\n").as_bytes())
}

/// Writes one line to stderr -- for interactive wizard narration
/// (`callisto add`'s step prompts), which must stay off stdout so a script
/// piping stdout never sees prompt text mixed into a report or changeset preview.
pub fn prompt_line(line: &str) {
    eprintln!("{line}");
}

pub fn log_line(format: OutputFormat, line: &str) -> io::Result<()> {
    match format {
        OutputFormat::Json => {
            eprintln!("{line}");
            Ok(())
        }
        OutputFormat::Text => emit_line(line),
    }
}

#[cfg(test)]
mod tests {
    use callisto_model::{Diagnostic, Report};
    use serde::Deserialize;

    use super::*;

    #[derive(Serialize, Deserialize)]
    struct FakeReport {
        value: u32,
    }

    impl callisto_model::Report for FakeReport {
        const COMMAND: &'static str = "fake-report";

        fn schema_version(&self) -> u32 {
            1
        }

        fn diagnostics(&self) -> &[Diagnostic] {
            &[]
        }
    }

    #[test]
    fn write_json_serializes_pretty_with_trailing_newline() {
        let mut buf = Vec::new();
        write_json(&mut buf, &FakeReport { value: 42 }).unwrap();
        let text = String::from_utf8(buf).unwrap();
        assert!(text.contains("\"value\": 42"), "got:\n{text}");

            config: config.clone(),
            snapshot: snapshot.clone(),
            action,
        })
    }

    /// Rejects any post-decision forge state change before the executor mutates.
    pub fn verify_snapshot(&self, observed: &ReleasePrSnapshotV2) -> Result<(), ReleasePrDecisionError> {
        if observed != &self.snapshot {
            return Err(ReleasePrDecisionError::SnapshotChanged);
        }
        Ok(())
    }
}

/// The on-the-wire shape of [`ReleasePrDecisionV2`], with its nested config and
/// snapshot still unvalidated. See [`ReleasePrConfigWireV1`] for why the CLI
/// deserializes this instead of `ReleasePrDecisionV2` directly.
#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleasePrDecisionWireV2 {
    pub schema_version: u8,
    pub config: ReleasePrConfigWireV1,
    pub snapshot: ReleasePrSnapshotWireV2,
    pub action: ReleasePrActionV2,
}

impl ReleasePrDecisionV2 {
    /// Validates an already-parsed wire value, including its nested config and snapshot,
    /// into a well-formed decision.
    pub fn from_wire(wire: ReleasePrDecisionWireV2) -> Result<Self, ReleasePrDecisionError> {
        check_schema_version(wire.schema_version, Self::SCHEMA_VERSION, "release PR decision")?;
        Ok(Self {
            schema_version: wire.schema_version,
            config: ReleasePrConfigV1::from_wire(wire.config)?,
            snapshot: ReleasePrSnapshotV2::from_wire(wire.snapshot)?,
            action: wire.action,
        })
    }
}

impl<'de> Deserialize<'de> for ReleasePrDecisionV2 {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleasePrDecisionWireV2::deserialize(deserializer)?;
        Self::from_wire(wire).map_err(serde::de::Error::custom)
    }
}

