//! Release interfaces: bare `release` (local), and the CI plan/execute route.
//!
//! Bare `release` publishes every unreleased package through the same
//! `execute_release` route as `release execute`. The CI route accepts only
//! exact package identities and explicit intent, receipt, and orchestration
//! revision paths.

use std::process::ExitCode;

use callisto_graph::commands::{
    build_release_intent, build_release_intent_with_artifacts, ci_release_route, derive_release_commit_decision,
    derive_selected_release_decision, execute_release, plan_local_release, validate_local_release_intent,
    validate_release_intent, verify_artifact_manifest, LocalReleasePlan, LocalReleaseSource, VersionOptions,
};
use callisto_graph::locate::IgnoreWalkLocator;
use callisto_model::{
    ApplyPermit, ArtifactDigest, ArtifactManifestEntryV1, ArtifactManifestV1, ExecutionTrustProfileV1,
    GitHubArtifactAttestationV1, PackageId, ReleaseArtifactManifestReport, ReleaseDryRunReport, ReleaseExecuteReport,
    ReleaseIntentV1, ReleaseIntentV1Wire, ReleaseNothingReport, ReleasePackageId, ReleasePlanReport, ReleaseReceiptV1,
    ReleaseReport, ReleaseRunEnvelopeV1,
};

use crate::cli::{
    GlobalArgs, OutputFormat, ReleaseArgs, ReleaseArtifactManifestArgs, ReleaseCommandArgs, ReleaseExecuteArgs,
    ReleaseInspectArgs, ReleasePlanArgs,
};
use crate::error::CliError;
use crate::output::{emit_line, emit_report, log_line, write_json};
use crate::runner::CliCommandRunner;
use crate::workspace::{load_workspace, select_inference};

pub fn handle(args: ReleaseCommandArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    match args.command {
        None => release(&args.packages, args.receipt, global),
        Some(ReleaseArgs::Plan(args)) => plan(args, global),
        Some(ReleaseArgs::Inspect(args)) => inspect(args, global),
        Some(ReleaseArgs::ArtifactManifest(args)) => artifact_manifest(args, global),
        Some(ReleaseArgs::Execute(args)) => execute(args, global),
    }
}

/// Stderr note when a preview's tags have no `origin` to push to.
pub const TAGS_UNBOUND_NOTE: &str =
    "note: `origin` has no push URL, so tag operations are unbound; `callisto release` will refuse until one is set";

/// Exact stdout when no package has an unreleased version.
pub const NOTHING_TO_RELEASE: &str = "Nothing to release.";

fn release(
    packages: &[String],
    receipt: Option<std::path::PathBuf>,
    global: &GlobalArgs,
) -> Result<ExitCode, CliError> {
    let selections = parse_selections(packages)?;
    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let root = workspace.root.clone();
    let locator = IgnoreWalkLocator::new(&root);
    if global.dry_run {
        let plan = plan_local_release(&root, &locator, &runner, &selections, LocalReleaseSource::Preview)?;
        write_release_preview(plan.as_ref(), global.format, &mut std::io::stdout())?;
        return Ok(ExitCode::SUCCESS);
    }
    if let Some(route) = ci_release_route(&workspace)? {
        return Err(CliError::ReleaseRequiresCiRoute {
            reason: route.to_string(),
        });
    }
    let Some(plan) = plan_local_release(&root, &locator, &runner, &selections, LocalReleaseSource::Trusted)? else {
        print_nothing_to_release(global)?;
        return Ok(ExitCode::SUCCESS);
    };
    for diagnostic in &plan.diagnostics {
        eprintln!("warning: {}", diagnostic.message);
    }
    let intent = plan.intent;
    let permit = ApplyPermit::granted_unless_dry_run(false).expect("non-dry-run permits writes");
    // A receipt records only full success; a partial run is recovered by rerunning.
    if let Some(path) = &receipt {
        callisto_model::atomic::probe_atomic_write(path, &permit).map_err(|source| CliError::Io {
            source,
            path: Some(path.clone()),
        })?;
    }
    let callisto_model::SourceIdentity::GitCommit { sha } = &intent.snapshot.source else {
        return Err(CliError::ReleaseEnvelopeInvalid {
            detail: "a local release source must be a Git commit".to_owned(),
        });
    };
    // A local run is its own orchestration, so both revisions are the source commit.
    let envelope =
        ReleaseRunEnvelopeV1::new(sha.clone(), &intent, None).map_err(|error| CliError::ReleaseEnvelopeInvalid {
            detail: error.to_string(),
        })?;
    let capability = validate_local_release_intent(&root, &locator, &runner, intent)?;
    let state = execute_release(&capability, &permit, &envelope, None)?;
    let receipt_document =
        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
            detail: error.to_string(),
        })?;
    if let Some(path) = &receipt {
        write_receipt(path, &receipt_document, &permit)?;
    }
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleaseReport {
                receipt: receipt_document.clone(),
            },
            global.dry_run,
        )?,
        OutputFormat::Text => {
            let released = capability.intent().decision.entries.len();
            match &receipt {
                Some(path) => emit_line(&format!(
                    "Released {released} package(s); receipt saved to {}",
                    path.display()
                ))?,
                None => emit_line(&format!("Released {released} package(s)"))?,
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

/// Writes a `release --dry-run` preview of `plan`; `init` shows the same one.
pub(crate) fn write_release_preview(
    plan: Option<&LocalReleasePlan>,
    format: OutputFormat,
    out: &mut dyn std::io::Write,
) -> Result<(), CliError> {
    match (plan, format) {
        (None, OutputFormat::Json) => emit_report(
            &mut &mut *out,
            &ReleaseNothingReport {
                nothing_to_release: true,
            },
            true,
        )?,
        (None, OutputFormat::Text) => writeln!(out, "{NOTHING_TO_RELEASE}")?,
        (Some(plan), OutputFormat::Json) => emit_report(
            &mut &mut *out,
            &ReleaseDryRunReport {
                intent: plan.intent.clone(),
                diagnostics: plan.diagnostics.clone(),
            },
            true,
        )?,
        (Some(plan), OutputFormat::Text) => {
            write!(out, "{}", render_release_plan(&plan.intent, crate::color::enabled()))?
        }
    }
    if let Some(plan) = plan {
        if plan.tags_unbound {
            eprintln!("{TAGS_UNBOUND_NOTE}");
        }
        for diagnostic in &plan.diagnostics {
            eprintln!("warning: {}", diagnostic.message);
        }
    }
    Ok(())
}

fn print_nothing_to_release(global: &GlobalArgs) -> Result<(), CliError> {
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleaseNothingReport {
                nothing_to_release: true,
            },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(NOTHING_TO_RELEASE)?,
    }
    Ok(())
}

fn parse_selections(packages: &[String]) -> Result<Vec<ReleasePackageId>, CliError> {
    packages.iter().map(|raw| parse_release_selection(raw)).collect()
}

/// Parses one `--package` release selection, accepting `eco:name` as an input
/// alias for the canonical `eco/name` form (one id grammar, everywhere) --
/// `ReleasePackageId::parse`'s own strict `eco/name`-only grammar stays as is
/// for its durable, on-disk encoding (the release-decision file), which this
/// never reads back through.
fn parse_release_selection(raw: &str) -> Result<ReleasePackageId, CliError> {
    match PackageId::parse(raw) {
        Ok(PackageId::Prefixed { ecosystem, name }) => {
            ReleasePackageId::new(ecosystem, name).map_err(|error| CliError::ReleasePackageInvalid {
                raw: raw.to_string(),
                detail: error.to_string(),
            })
        }
        _ => Err(CliError::ReleasePackageInvalid {
            raw: raw.to_string(),
            detail: "expected an ecosystem-qualified package id, e.g. `cargo/pkg` or `cargo:pkg`".to_string(),
        }),
    }
}

/// One-line description of a release operation, shared by both the plain and table renderers.
fn describe_operation(operation: &callisto_model::ReleaseOperation) -> String {
    match &operation.id().role {
        callisto_model::ReleaseOperationRole::RegistryPublish { registry } => {
            format!("publish to {}", registry.registry_key().display_name())
        }
        callisto_model::ReleaseOperationRole::PlatformPublish { registry, platform } => {
            format!(
                "publish {} to {}",
                platform.name(),
                registry.registry_key().display_name()
            )
        }
        callisto_model::ReleaseOperationRole::Tag => "create git tag".to_owned(),
        callisto_model::ReleaseOperationRole::ForgeRelease => "create GitHub release draft".to_owned(),
        callisto_model::ReleaseOperationRole::ArtifactUpload { slot } => {
            format!("upload {}", slot.asset_name)
        }
        callisto_model::ReleaseOperationRole::ForgePublish => "publish GitHub release".to_owned(),
    }
}

/// Human-readable plan: each package and version, then its operations.
///
/// `use_color` is the one color/table decision ([`crate::color::enabled`]):
/// box-drawing table formatting renders only alongside color, never independently.
fn render_release_plan(intent: &ReleaseIntentV1, use_color: bool) -> String {
    let mut out = String::from("Release plan:\n");
    if use_color {
        out.push_str(&render_release_plan_table(intent));
        return out;
    }
    for entry in &intent.decision.entries {
        out.push_str(&format!("  {} {}\n", entry.package, entry.target_version));
        for operation in intent.operations.iter().filter(|op| op.id().package == entry.package) {
            out.push_str(&format!("    - {}\n", describe_operation(operation)));
        }
    }
    out
}

fn render_release_plan_table(intent: &ReleaseIntentV1) -> String {
    use comfy_table::{presets::UTF8_FULL, Cell, Color, Table};

    let mut table = Table::new();
    // Our `use_color` gate is the sole authority -- never let comfy-table's own
    // TTY probe override it, so a forced/piped stdout still renders styled.
    table.force_no_tty().enforce_styling();
    table.load_preset(UTF8_FULL);
    table.set_header(vec!["Package", "Version", "Operations"]);
    for entry in &intent.decision.entries {
        let steps: Vec<String> = intent
            .operations
            .iter()
            .filter(|op| op.id().package == entry.package)
            .map(describe_operation)
            .collect();
        table.add_row(vec![
            Cell::new(entry.package.to_string()),
            Cell::new(entry.target_version.to_string()).fg(Color::Green),
            Cell::new(steps.join("\n")),
        ]);
    }
    format!("{table}\n")
}

fn artifact_manifest(args: ReleaseArtifactManifestArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    if global.dry_run {
        return Err(CliError::ReleaseArtifactManifestDryRun);
    }
    let intent = read_intent(&args.intent)?;
    if intent.artifact_slots.is_empty() {
        return Err(CliError::ReleaseNoArtifactSlots);
    }
    let root = args.artifact_dir.canonicalize().map_err(|source| CliError::Io {
        source,
        path: Some(args.artifact_dir.clone()),
    })?;
    if !matches!(intent.snapshot.source, callisto_model::SourceIdentity::GitCommit { .. }) {
        return Err(CliError::ReleaseManifestSourceNotGit);
    }
    let mut entries = Vec::with_capacity(intent.artifact_slots.len());
    for slot in &intent.artifact_slots {
        let path = root.join(&slot.asset_name);
        let metadata = std::fs::symlink_metadata(&path).map_err(|source| CliError::Io {
            source,
            path: Some(path.clone()),
        })?;
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err(CliError::ReleaseArtifactNotRegularFile {
                asset: slot.asset_name.to_string(),
                dir: root.display().to_string(),
            });
        }
        let canonical = path.canonicalize().map_err(|source| CliError::Io {
            source,
            path: Some(path.clone()),
        })?;
        if !canonical.starts_with(&root) {
            return Err(CliError::ReleaseArtifactEscapesDirectory {
                asset: slot.asset_name.to_string(),
                dir: root.display().to_string(),
            });
        }
        let file = std::fs::File::open(&canonical).map_err(|source| CliError::Io {
            source,
            path: Some(canonical.clone()),
        })?;
        let (digest, byte_length) = ArtifactDigest::from_reader(file).map_err(|source| CliError::Io {
            source,
            path: Some(canonical),
        })?;
        entries.push(ArtifactManifestEntryV1 {
            slot: slot.clone(),
            digest: digest.clone(),
            byte_length,
            attestation: GitHubArtifactAttestationV1 {
                repository: slot.attestation_policy.repository.clone(),
                workflow_path: slot.attestation_policy.workflow_path.clone(),
                workflow_commit: slot.attestation_policy.workflow_commit.clone(),
                subject_digest: digest,
                source_commit: slot.attestation_policy.workflow_commit.clone(),
            },
        });
    }
    let manifest = ArtifactManifestV1::new(&intent, entries).map_err(|error| CliError::ReleaseManifestInvalid {
        detail: error.to_string(),
    })?;
    let permit = ApplyPermit::granted_unless_dry_run(false).expect("non-dry-run permits writes");

//! Deterministic, graph-owned release roster decisions.
//!
//! It records the exact package/version authority that later intent construction consumes, without
//! exposing a mutation route.

use callisto_model::{
    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
    ReleaseInclusionReason, ReleasePackageId, Version,
};

use crate::error::{
    CommandFailure, CommitVerificationFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason,
    UnsupportedReleaseFeature,
};
use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};

/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
/// against `package`'s name.
///
/// This is the single derivation of release package identity shared by every
/// site that computes or verifies release authority: [`derive_release_decision`],
/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
/// Per this module's own established lesson (see the doc comment on
/// [`derive_release_commit_decision`]), independently reimplementing this
/// mapping at each call site is exactly the kind of duplicated derivation
/// that drifts -- so it lives here once instead.
pub(crate) fn release_package_ids(
    identity: &crate::IdentityIndex,
    package: &Package,
) -> Result<Vec<ReleasePackageId>, GraphError> {
    package
        .canonical_manifests()
        .map(|manifest| {
            let ecosystem = manifest.ecosystem();
            // A dual-manifest package's manifests may declare different names.
            let name = identity
                .native_name(&package.id, ecosystem)
                .unwrap_or(package.id.name());
            ReleasePackageId::new(ecosystem, name)
        })
        .collect::<Result<Vec<_>, _>>()
        .map_err(GraphError::from)
}

/// Derives the durable roster from a freshly computed version plan.
///
/// The caller supplies the plan from the same workspace observation; this
/// function never inspects a caller-provided release roster.
pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
) -> Result<ReleaseDecisionV1, GraphError> {
    let mut package_ids = std::collections::BTreeMap::new();
    for package in workspace.graph.packages() {
        let ids = release_package_ids(&workspace.identity, package)?;
        package_ids.insert(package.id.clone(), ids);
    }

    let mut entries = Vec::new();
    for bump in &plan.bumps {
        // `plan` is contractually derived from this same workspace
        // observation (see doc comment above), so every bump's package must
        // already be a key here -- a miss means the plan/workspace pairing
        // itself is inconsistent, not a recoverable operator condition.
        let ids = package_ids
            .get(&bump.package)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!(
                    "version plan references package `{}`, which is absent from this workspace observation",
                    bump.package.display_name()
                ),
            })?;
        for id in ids {
            entries.push(ReleaseDecisionEntry {
                package: id.clone(),
                target_version: bump.to.clone(),
                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
            });
        }
    }
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Derives a durable decision for explicit, exact release identities.
///
/// A linked group is one release unit: selecting any member includes every
/// member of that linked group which the version plan selected. All other
/// packages remain outside the authority boundary. The caller must pass
/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
/// for release authority.
pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
    selections: &[ReleasePackageId],
) -> Result<ReleaseDecisionV1, GraphError> {
    let complete = derive_release_decision(workspace, plan)?;

    let mut seen = std::collections::BTreeSet::new();
    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
        return Err(GraphError::ReleaseSelectionInvalid {
            package: duplicate.clone(),
            reason: ReleaseSelectionInvalidReason::Duplicate,
        });
    }

    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    for selection in &selected {
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        let reason = if !complete.entries.iter().any(|entry| &entry.package == *selection) {
            ReleaseSelectionInvalidReason::NotARelease
        } else if package
            .publish_to
            .iter()
            .all(|target| matches!(target, callisto_model::PublishTarget::None))
        {
            ReleaseSelectionInvalidReason::NoDispatchableTarget
        } else {
            continue;
        };
        return Err(GraphError::ReleaseSelectionInvalid {
            package: (*selection).clone(),
            reason,
        });
    }

    let entries = expand_selection(workspace, complete.entries, &selected);
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Keeps the selected entries plus every entry sharing a fixed or linked group
/// with a selection. Both release routes narrow `--package` through this.
fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    entries: Vec<ReleaseDecisionEntry>,
    selected: &std::collections::BTreeSet<&ReleasePackageId>,
) -> Vec<ReleaseDecisionEntry> {
    // A plan-derived entry carries its linked group as a reason.
    let reason_groups = entries
        .iter()
        .filter(|entry| selected.contains(&entry.package))
        .flat_map(|entry| entry.reasons.iter())
        .filter_map(|reason| match reason {
            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
            _ => None,
        })
        .collect::<std::collections::BTreeSet<_>>();
    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
    let config_groups = selected
        .iter()
        .flat_map(|selection| release_groups_of(workspace, selection))
        .collect::<std::collections::BTreeSet<_>>();
    entries
        .into_iter()
        .filter(|entry| {
            selected.contains(&entry.package)
                || entry.reasons.iter().any(|reason| {
                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
                })
                || release_groups_of(workspace, &entry.package)
                    .iter()
                    .any(|group| config_groups.contains(group))
        })
        .collect()
}

/// Derives the roster of every publishable package whose current version has
/// no tag in the canonical [`crate::TagIndex`], each with
/// [`ReleaseInclusionReason::UnreleasedVersion`].
///
/// A non-empty `selections` restricts the roster to exactly those identities,
/// each of which must be unreleased and publishable. `None` means nothing is
/// unreleased.
pub fn derive_unreleased_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
) -> Result<Option<ReleaseDecisionV1>, GraphError> {
    let versions = workspace.base_versions()?;
    let tags = workspace.tags()?;
    let mut entries = Vec::new();
    for package in workspace.graph.packages() {
        if !has_dispatchable_target(package) {
            continue;
        }
        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!("package `{}` has no base version", package.id.display_name()),
        })?;
        if version_is_tagged(tags, &package.id, version) {
            continue;
        }
        for id in release_package_ids(&workspace.identity, package)? {
            entries.push(ReleaseDecisionEntry {
                package: id,
                target_version: version.clone(),
                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
            });
        }
    }

    let mut seen = std::collections::BTreeSet::new();
    for selection in selections {
        if !seen.insert(selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::Duplicate,
            });
        }
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        if !has_dispatchable_target(package) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
            });
        }
        if !entries.iter().any(|entry| &entry.package == selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NotARelease,
            });
        }
    }
    if !selections.is_empty() {
        entries = expand_selection(workspace, entries, &seen);
    }
    if entries.is_empty() {
        return Ok(None);
    }
    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
}

/// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
pub(crate) fn version_is_tagged(
