use std::process::ExitCode;

use callisto_model::format::{Changeset, PreState};
use callisto_model::{InitReport, MatrixReport, ReleaseReceiptV1, SnapshotReport, StatusReport, VersionReport};
use schemars::schema_for;

use crate::cli::{GlobalArgs, SchemaArgs, SchemaReportType};
use crate::error::CliError;
use crate::output::write_stdout;

pub fn handle(args: SchemaArgs, _global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let schema = match args.target_type.unwrap_or_default() {
        SchemaReportType::Status => schema_for!(StatusReport),
        SchemaReportType::Version => schema_for!(VersionReport),
        SchemaReportType::Snapshot => schema_for!(SnapshotReport),
        SchemaReportType::Init => schema_for!(InitReport),
        SchemaReportType::Changeset => schema_for!(Changeset),
        SchemaReportType::PreState => schema_for!(PreState),
        SchemaReportType::Matrix => schema_for!(MatrixReport),
        SchemaReportType::ReleaseReceipt => schema_for!(ReleaseReceiptV1),
    };

    // A `schemars::Schema` is a plain JSON tree of strings, numbers, and nested maps;
    // it always serializes.
    let json = serde_json::to_string_pretty(&schema).expect("schema serializes");
    write_stdout(format!("{json}\n").as_bytes())?;
    Ok(ExitCode::SUCCESS)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn global() -> GlobalArgs {
        GlobalArgs {
            format: crate::cli::OutputFormat::Text,
            cwd: std::path::PathBuf::from("."),
            dry_run: false,
        }
    }

    /// Every registry entry actually produces a schema; an unknown `--type`
    /// value is rejected earlier, at clap parse time (see `cli.rs`'s
    /// `schema_type_rejects_unknown_value_as_a_usage_error`), so this
    /// handler-level test only needs to cover the exhaustive match's arms.
    #[test]
    fn handle_succeeds_for_every_registered_type() {
        for target_type in [
            SchemaReportType::Status,
            SchemaReportType::Version,
            SchemaReportType::Snapshot,
            SchemaReportType::Init,
            SchemaReportType::Changeset,
            SchemaReportType::PreState,
            SchemaReportType::Matrix,
            SchemaReportType::ReleaseReceipt,
        ] {
            let result = handle(
                SchemaArgs {
                    target_type: Some(target_type),
                },
                &global(),
            );
            assert!(result.is_ok(), "target_type={target_type:?}");
        }
    }
}

    /// Constructs a receipt from a terminal state alone: every operation must
    /// be successful, and its recorded evidence becomes its observation.
    ///
    /// The run envelope comes from the state, which was created and validated
    /// before the first effect; nothing is assembled after the fact here.
    pub fn from_state(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<Self, ReleaseReceiptError> {
        state
            .validate_for_intent(intent)
            .map_err(ReleaseReceiptError::InvalidState)?;
        let mut outcomes = BTreeMap::new();
        let mut observations = BTreeMap::new();
        for (id, operation_state) in &state.operations {
            let outcome = match operation_state {
                OperationState::Published => OperationOutcome::Published,
                OperationState::AlreadySatisfied => OperationOutcome::AlreadySatisfied,
                OperationState::Failed | OperationState::Blocked { .. } => {
                    return Err(ReleaseReceiptError::NonSuccessfulOperation {
                        id: Box::new(id.clone()),
                    });
                }
                OperationState::Pending | OperationState::Attempting => {
                    return Err(ReleaseReceiptError::NonTerminalOperation {
                        id: Box::new(id.clone()),
                    });
                }
            };
            let evidence = state.operation_evidence(id).cloned().ok_or_else(|| {
                ReleaseReceiptError::InvalidState(ReleaseStateError::MissingEvidence {
                    id: Box::new(id.clone()),
                })
            })?;
            outcomes.insert(id.clone(), outcome);
            observations.insert(id.clone(), ProviderObservationV1::Exact { evidence });
        }
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            intent_digest: state.intent_digest.clone(),
            envelope: state.envelope().clone(),
            outcomes,
            observations,
        })
    }

    /// The exact provider observation this receipt records for `id`.
    pub fn observation(&self, id: &ReleaseOperationId) -> Option<&ProviderObservationV1> {
        self.observations.get(id)
    }

    pub fn intent_digest(&self) -> &IntentDigest {
        &self.intent_digest
    }

    /// Validates exact intent and operation-roster binding before reconciliation.
    pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ReleaseReceiptError> {
        if self.schema_version != Self::SCHEMA_VERSION {
            return Err(ReleaseReceiptError::UnsupportedSchema {
                found: self.schema_version,
            });
        }
        if self.intent_digest != intent.digest {
            return Err(ReleaseReceiptError::MismatchedIntent);
        }
        self.envelope
            .validate_for_intent(intent)
            .map_err(ReleaseReceiptError::InvalidEnvelope)?;
        let expected: BTreeSet<_> = intent.operations.iter().map(|operation| operation.id.clone()).collect();
        let actual: BTreeSet<_> = self.outcomes.keys().cloned().collect();
        if actual != expected {
            return Err(ReleaseReceiptError::MismatchedOperationRoster);
        }
        let observed: BTreeSet<_> = self.observations.keys().cloned().collect();
        if observed != expected {
            return Err(ReleaseReceiptError::MismatchedObservationRoster);
        }
        if self
            .observations
            .values()
            .any(|observation| !observation.is_terminal_success())
        {
            return Err(ReleaseReceiptError::NonExactReceiptObservation);
        }
        Ok(())
    }

    fn from_wire(wire: ReleaseReceiptV1Wire) -> Result<Self, ReleaseReceiptError> {
        if wire.schema_version != Self::SCHEMA_VERSION {
            return Err(ReleaseReceiptError::UnsupportedSchema {
                found: wire.schema_version,
            });
        }
        let mut outcomes = BTreeMap::new();
        for entry in wire.outcomes {
            if !matches!(
                entry.outcome,
                OperationOutcome::Published | OperationOutcome::AlreadySatisfied
            ) {
                return Err(ReleaseReceiptError::NonSuccessfulOperation {
                    id: Box::new(entry.operation),
                });
            }
            if outcomes.insert(entry.operation.clone(), entry.outcome).is_some() {
                return Err(ReleaseReceiptError::DuplicateOperation {
                    id: Box::new(entry.operation),
                });
            }
        }
        let mut observations = BTreeMap::new();
        for entry in wire.observations {
            let (operation, observation) = entry.into_parts();
            if !observation.is_terminal_success() {
                return Err(ReleaseReceiptError::NonExactObservation {
                    id: Box::new(operation),
                    observation: Box::new(observation),
                });
            }
            if observations.insert(operation.clone(), observation).is_some() {
                return Err(ReleaseReceiptError::DuplicateObservation {
                    id: Box::new(operation),
                });
            }
        }
        Ok(Self {
            schema_version: wire.schema_version,
            intent_digest: wire.intent_digest,
            envelope: wire.envelope,
            outcomes,
            observations,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum ReleaseReceiptError {
    #[error("unsupported release receipt schema version {found}")]
    UnsupportedSchema { found: u8 },
    #[error("release receipt is bound to a different intent")]
    MismatchedIntent,
    #[error("release receipt operation roster differs from the bound intent")]
    MismatchedOperationRoster,
    #[error("release receipt contains duplicate operation `{id:?}")]
    DuplicateOperation { id: Box<ReleaseOperationId> },
    #[error("release receipt cannot be derived from invalid state: {0}")]
    InvalidState(ReleaseStateError),
    #[error("release receipt envelope is not bound to the intent: {0}")]
    InvalidEnvelope(ReleaseRunEnvelopeError),
    #[error("release operation `{id:?}` is not terminal")]
    NonTerminalOperation { id: Box<ReleaseOperationId> },
    #[error("release operation `{id:?}` did not complete successfully")]
    NonSuccessfulOperation { id: Box<ReleaseOperationId> },
    #[error("release receipt observation roster differs from the bound intent")]
    MismatchedObservationRoster,
    #[error("release receipt contains duplicate observation for `{id:?}`")]
    DuplicateObservation { id: Box<ReleaseOperationId> },
    #[error("release receipt observation for `{id:?}` is not exact: {observation:?}")]
    NonExactObservation {
        id: Box<ReleaseOperationId>,
        observation: Box<ProviderObservationV1>,
    },
    #[error("release receipt contains a non-exact provider observation")]
    NonExactReceiptObservation,
}

/// `callisto release --format json` report: flattens [`ReleaseReceiptV1`] so its own
/// fields reach stdout unchanged, through the one envelope every command shares.

//! Guards every report struct's field shape against an accidental schema change. The
//! `StatusReport.pending` field is mandatory (count of packages with a planned bump --
//! `status --check`'s 0/1 exit code doesn't itself signal pending state, so this is how a
//! script detects it). The `tag` and `plan-publish` report schemas left with their commands.
//! Expected sets below were captured from `callisto schema` against the live repository;
//! update them deliberately alongside a `DiagnosticCode` or report field change.

use std::collections::BTreeSet;
use std::process::Command;

fn run_schema(target: &str) -> serde_json::Value {
    let bin = env!("CARGO_BIN_EXE_callisto");
    let out = Command::new(bin)
        .args(["schema", "--type", target])
        .output()
        .expect("callisto schema must run");
    assert!(
        out.status.success(),
        "callisto schema --type {target} failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    serde_json::from_slice(&out.stdout).expect("schema output must be valid JSON")
}

fn required_and_props(schema: &serde_json::Value) -> (BTreeSet<String>, BTreeSet<String>) {
    let required: BTreeSet<String> = schema["required"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let props: BTreeSet<String> = schema["properties"].as_object().unwrap().keys().cloned().collect();
    (required, props)
}

fn set(items: &[&str]) -> BTreeSet<String> {
    items.iter().map(|s| s.to_string()).collect()
}

#[test]
fn report_struct_field_shapes_are_unchanged() {
    let status_schema = run_schema("status");
    let (req, props) = required_and_props(&status_schema);
    assert_eq!(req, set(&["hasChangesets", "packages", "pending", "schemaVersion"]));
    assert_eq!(
        props,
        set(&["diagnostics", "hasChangesets", "packages", "pending", "schemaVersion"])
    );
}

#[test]
fn diagnostic_code_enum_variants_match_expected_set() {
    let status_schema = run_schema("status");
    let variants: BTreeSet<String> = status_schema["definitions"]["DiagnosticCode"]["oneOf"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v["enum"][0].as_str().unwrap().to_string())
        .collect();

    let expected = set(&[
        "empty-changeset",
        "empty-summary",
        "unknown-package",
        "invalid-package-name",
        "napi-target-added-not-in-members",
        "napi-target-removed-still-on-disk",
        "napi-coordination-not-yet-supported",
        "range-not-round-trippable",
        "catalog-spec-not-rewritten",
        "tag-glob-non-version-match",
        "changesets-config-key-dropped",
        "pre-major-inference-inert",
        "changelog-section-not-found",
        "changeset-read-error",
        "changeset-parse-failed",
        "git-discovery-failed",
        "init-origin-missing",
        "bare-rule-matches-multiple-ecosystems",
        "unrecognised-platform-triple",
        "publish-target-not-implemented",
        "package-set-matched-nothing",
        "duplicate-platform-triple",
        "changelog-read-error",
        "ambiguous-package-name",
        "platform-package-without-owner",
        "workflow-generation-unsupported",
        "workflow-merge-publishes",
        "package-rule-matched-nothing",
        "product-artifact-owner-without-product",
    ]);

    assert_eq!(
        variants, expected,
        "DiagnosticCode schema variants changed; update this list deliberately"
    );
}

/// The receipt is versioned: a change to its shape without a `SCHEMA_VERSION`
/// bump is a silent break for receipts written by an earlier release. The
/// receipt is at version 2 and its run envelope at version 3 (no run kind, no profile).
#[test]
fn durable_release_wire_shapes_match_their_schema_version() {
    let receipt = run_schema("release-receipt");
    let (req, props) = required_and_props(&receipt);
    let expected = set(&["schemaVersion", "intentDigest", "envelope", "outcomes", "observations"]);
    assert_eq!(req, expected);
    assert_eq!(props, expected);

    let (req, props) = required_and_props(&receipt["definitions"]["ReleaseRunEnvelopeV1"]);
    let mut expected = set(&[
        "schemaVersion",
        "orchestrationRevision",
        "releaseSourceRevision",
        "intentDigest",
    ]);
    assert_eq!(req, expected);
    expected.insert("artifactManifestDigest".to_owned());
    assert_eq!(props, expected);
}

/// The operation role is the durable DAG's vocabulary: a receipt names every
/// operation by it. `forgePublish` is the role that makes publication the last
/// forge step, after every `artifactUpload`.
#[test]
fn release_operation_roles_carry_exactly_their_declared_variants() {
    let receipt = run_schema("release-receipt");
    let variants: BTreeSet<String> = receipt["definitions"]["ReleaseOperationRole"]["oneOf"]
        .as_array()
        .unwrap()
        .iter()
        .map(|variant| {
            variant["properties"]["kind"]["enum"][0]
                .as_str()
                .expect("every role variant names itself")
                .to_owned()
        })
        .collect();
    assert_eq!(
        variants,
        set(&[
            "registryPublish",
            "tag",
            "forgeRelease",
            "artifactUpload",
            "forgePublish",
            "platformPublish",
        ])
    );
}

/// Both observation enums are closed and persisted in receipts, so a
/// reader from an earlier release must be able to name every value it can meet.
/// Adding one is intentional and belongs here; losing one silently is not.
#[test]
fn provider_observation_enums_carry_exactly_their_declared_variants() {
    let receipt = run_schema("release-receipt");
    let variants = |name: &str| -> BTreeSet<String> {
        receipt["definitions"][name]["oneOf"]
            .as_array()
            .unwrap()
            .iter()
            .map(|variant| {
                variant["enum"]
                    .get(0)
                    .or_else(|| variant["properties"]["kind"]["enum"].get(0))
                    .and_then(serde_json::Value::as_str)
                    .expect("every variant names itself")
                    .to_owned()
            })

