        OutputFormat::Json => emit_report(&mut std::io::stdout(), &report, global.dry_run)?,
        OutputFormat::Text => render::render_matrix(&report, &mut std::io::stdout())?,
    }

    Ok(ExitCode::SUCCESS)
}

