function check(s, v, loc) {
  if (s.type) {
    const type = Array.isArray(v) ? 'array' : v === null ? 'null' : typeof v;
    if (type !== s.type) throw Error(loc + ': type');
  }
  if (s.enum && !s.enum.includes(v)) throw Error(loc + ': enum');
  if (s.type === 'object') {
    for (const k of s.required || []) if (!(k in v)) throw Error(loc + ': missing ' + k);
    for (const [k, val] of Object.entries(v)) {
      if (s.properties?.[k]) check(s.properties[k], val, loc + '.' + k);
      else if (s.additionalProperties === false) throw Error(loc + ': extra ' + k);
    }
  }
  if (s.type === 'array') {
    if (v.length < (s.minItems || 0)) throw Error(loc + ': length');
    if (s.items) v.forEach((val, i) => check(s.items, val, loc + '[' + i + ']'));
  }
}
const specSchema = read(path.join(base, 'spec@1.json'));
const specs = fs.readdirSync('docs/specs').filter(p => p.endsWith('.json'));
const criteria = new Set();
for (const f of specs) {
  const doc = read('docs/specs/' + f);
  check(specSchema, doc, f);
  for (const c of doc.acceptance_criteria) {
    if (criteria.has(c.id)) throw Error('duplicate criterion ' + c.id);
    criteria.add(c.id);
  }
}
const plan = read('docs/projects/V1-SYSTEM-HARDENING.json');
check(read(path.join(base, 'plan@1.json')), plan, 'plan');
const seen = new Set();
