  if (seen.has(t.id)) throw Error('duplicate task');
  for (const d of t.depends_on || []) if (!seen.has(d)) throw Error('unordered dependency ' + d);
  for (const c of t.covers_criteria || []) if (!criteria.has(c)) throw Error('missing criterion ' + c);
  for (const k of ['modify', 'test']) for (const f of t.files[k] || []) if (!fs.existsSync(f)) throw Error('missing file ' + f);
  seen.add(t.id);
}
for (const b of plan.batches || []) for (const id of b.task_ids || []) if (!seen.has(id)) throw Error('unknown batch task');
const findings = fs.readFileSync('docs/projects/V1-FINDINGS.md', 'utf8');
let mappings = 0;
for (const m of findings.matchAll(/^\| (SYS-[A-Z-]+) \|.*?\| (T\d+) \|/gm)) {
  const t = plan.tasks.find(t => t.id === m[2]);
  if (!t || !t.steps.some(s => s.includes(m[1]))) throw Error('uncovered ' + m[1]);
  mappings++;
}
const files = [...cp.execFileSync('git', ['diff', '--name-only'], {encoding:'utf8'}).trim().split('\n'), ...cp.execFileSync('git', ['ls-files', '--others', '--exclude-standard'], {encoding:'utf8'}).trim().split('\n')].filter(Boolean);
let links = 0;
for (const f of files) {
  if (!(f === 'ARCHITECTURE.md' || f === 'README.md' || f.startsWith('docs/'))) throw Error('non-doc edit ' + f);
  if (!f.endsWith('.md')) continue;
  for (const m of fs.readFileSync(f, 'utf8').matchAll(/\[[^\]\n]+\]\(([^)]+)\)/g)) {
