+        for kind in [DepKind::Runtime, DepKind::Optional, DepKind::Peer, DepKind::Dev] {
+            let rewrite = outcome
+                .rewrites
+                .values()
+                .find(|rewrite| rewrite.key.name == "@scope/core" && rewrite.key.kind == Some(kind))
+                .unwrap();
+            assert_eq!(rewrite.dependency, core);
+            assert_eq!(rewrite.key.target, DepWriteTarget::Manifest("crates/app/package.json".into()));
+            assert_eq!(rewrite.to.render(), target, "npm rewrites must follow npm's range policy");
