+    assert_eq!(ws.graph.dependents_of(&target).count(), 1);
+    assert_eq!(ws.identity.native_name(&target, Ecosystem::Pypi), Some(native_name));
+    assert!(ws.identity.native.contains_key(&(Ecosystem::Pypi, native_name.to_string())));
