                GraphError::Command(CommandError::Failed {
                    program,
                    exit_code: Some(128),
                    stderr
                }) if program == "git" && stderr.contains("unable to read index")
            ),
            "unexpected result for {failed_args:?}: {error:?}"
        );
    }
