pub const VERSIONING_PROMPT: &str = "How should packages be versioned?";
pub const SHIP_PROMPT: &str = "Ship binaries as GitHub release assets?";
pub const PRODUCT_PROMPT: &str = "Which package is the product whose binaries ship?";
pub const FORGE_PROMPT: &str = "GitHub repository to release to (owner/repo)";
pub const TARGETS_PROMPT: &str = "Artifact target triples (comma-separated)";
pub const WRITE_PROMPT: &str = "Write callisto.toml?";
pub const WORKFLOW_PROMPT: &str = "Generate a GitHub Actions release workflow?";
/// Printed instead of the preview when the repository has no commit to plan from.
pub const NO_COMMITS: &str =
    "No commits yet: commit, then run `callisto release --dry-run` to preview the first release.";
/// Printed instead of asking `WORKFLOW_PROMPT` for a workspace no generated workflow covers.
fn workflow_unsupported_note(reason: scaffold::WorkflowUnsupported) -> String {
    format!("Skipping GitHub Actions workflow generation: {reason}.")
}
/// Printed once a generated workflow is written: a merge to `branch` is the release approval.
fn merge_publishes_note(branch: &str) -> String {
    format!(
        "Merging to `{branch}` publishes: require pull requests and reviews on `{branch}` (GitHub → Settings → Rules)."
    )
}
const VERSIONING_CHOICES: [&str; 2] = [
    "independent: each package has its own version",
    "fixed: every package shares one version",
];

/// Asks the operator questions; a scripted implementation drives tests.
pub trait Prompter {
    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError>;
    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError>;
}

struct TerminalPrompter;

impl Prompter for TerminalPrompter {
    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError> {
        Ok(Select::new().with_prompt(prompt).items(items).default(0).interact()?)
    }

    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
        Ok(Confirm::new().with_prompt(prompt).default(default).interact()?)
    }

    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError> {
        let mut input = Input::<String>::new().with_prompt(prompt);
        if let Some(default) = default {
            input = input.default(default.to_owned());
        }
        Ok(input.interact_text()?)
    }
}

pub fn handle(args: InitArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    run(
        args,
        global,
        tty::is_interactive(),
        &mut TerminalPrompter,
        &mut std::io::stdout(),
        &mut std::io::stderr(),
        &CliCommandRunner,
    )
}

/// `init` against explicit terminal state, prompter, output streams, and command runner.
pub fn run<R: CommandRunner>(
    args: InitArgs,
    global: &GlobalArgs,
    interactive: bool,
    prompter: &mut dyn Prompter,
    out: &mut dyn Write,
    err: &mut dyn Write,
    runner: &R,
) -> Result<ExitCode, CliError> {
    validate_flags(&args)?;
    let root = workspace_root(global, runner)?;
    let locator = IgnoreWalkLocator::new(&root);
    let facts = scaffold::detect(&root, &locator, runner)?;
    let json = global.format == OutputFormat::Json;

    #[diagnostic(
        code(E194),
        help("Give each package its own [[package]] `tag-template` (and `previous-tag-templates` for the shared `v{{version}}` tags).")
    )]
    InitSharedVersionTag { packages: Vec<String> },

    #[error("forge repository `{value}` is invalid: {reason}")]
    #[diagnostic(code(E195), help("Use the GitHub `owner/repo` the product releases to."))]
    InitInvalidForgeRepository { value: String, reason: String },

    #[error("forge repository `{configured}` does not match the origin remote `{origin}`")]
    #[diagnostic(
        code(E187),
        help("The release plan requires [release].forge-repository to be origin's GitHub repository. Use that `owner/repo`, or point origin at the repository binaries release to.")
    )]
    InitForgeRepositoryMismatch { configured: String, origin: String },

    #[error("artifact target `{triple}` is invalid: {reason}")]
    #[diagnostic(code(E196), help("Use distinct, non-empty Rust target triples."))]
    InitInvalidTargetTriple { triple: String, reason: &'static str },

    #[error("no package produces a binary artifact, so there is nothing to ship")]
    #[diagnostic(
        code(E188),
        help("Remove --artifact-target, or add a binary target ([[bin]], an npm `bin`, or [project.scripts]).")
    )]
    InitNoBinaryPackage,

    #[error("product package `{package}` is invalid: {reason}")]
    #[diagnostic(code(E189), help("Name one of the binary-producing packages: {}.", .candidates.join(", ")))]
    InitInvalidProductPackage {
        package: String,
        reason: &'static str,
        candidates: Vec<String>,
    },

    #[error("`{}` already exists; init refuses to overwrite a generated workflow", .path.display())]
    #[diagnostic(
        code(E200),
        help("Remove or edit the existing file directly; `callisto init` never merges into it.")
    )]
    InitWorkflowExists { path: PathBuf },

    #[error("couldn't resolve callisto@{version} to a commit on orin-dx/callisto")]
    #[diagnostic(
        code(E201),
        help("check network access to github.com, or run `callisto init --no-workflow` to skip workflow generation")
    )]
    InitWorkflowVersionUnresolved { version: String },

    #[error("callisto init cannot generate a release workflow for this workspace: {reason}")]
    pub packages: Vec<InitPackage>,
    /// Canonical `origin` push URL, or `None` when no `origin` remote is configured.
    pub origin: Option<String>,
    /// `origin` as a GitHub `owner/repo`, when it is one.
    pub origin_repository: Option<GitHubRepository>,
    /// Non-default tag templates to write, keyed by qualified package id.
    pub tag_templates: BTreeMap<String, String>,
    /// `false` in a repository with no commit yet, where no release can be planned.
    pub has_commit: bool,
    /// A package ships napi/maturin platform builds -- either its own canonical
    /// manifest is platform-tagged, or a platform package is attached to it from
    /// a sibling directory (`IdentityIndex::platforms_of`, e.g. napi's per-arch
    /// packages). Mirrors `commands::release::local::ci_release_route`'s own
    /// platform-package check.
    pub has_platform_packages: bool,
    /// Some package declares `napi.targets` (`callisto matrix`'s napi entries).
    pub has_napi_targets: bool,
    /// Some package declares `[tool.maturin].targets`.
    pub has_maturin_targets: bool,
}

impl InitFacts {
    pub fn binary_packages(&self) -> impl Iterator<Item = &InitPackage> {
        self.packages.iter().filter(|package| package.is_binary())
    }

    /// Resolves `name` (qualified or bare) to a binary-producing package.
    pub fn product_package(&self, name: &str) -> Result<&InitPackage, GraphError> {
        let invalid = |reason| GraphError::InitInvalidProductPackage {
            package: name.to_owned(),
            reason,
            candidates: self.binary_packages().map(|package| package.id.clone()).collect(),
        };
        let found: Vec<&InitPackage> = match self.packages.iter().find(|package| package.id == name) {
            Some(package) => vec![package],
            None => self.packages.iter().filter(|package| package.name() == name).collect(),
        };
        match found.as_slice() {
            [package] if package.is_binary() => Ok(package),
            [_] => Err(invalid("it does not produce a binary artifact")),
            _ => Err(invalid("it is not a workspace package")),
        }
    }
}

