    // only the corresponding lockfiles are staged. Staging lockfiles whose
    // ecosystem was not touched can sweep up unrelated user changes.
    use callisto_model::Ecosystem;
    let active_ecosystems: std::collections::HashSet<Ecosystem> = plan
        .bumps
        .iter()
        .flat_map(|bump| {
            bump.package
                .ecosystem()
                .into_iter()
                .chain(bump.writes.iter().filter_map(|write| {
                    match write {
                        VersionWriteTarget::CargoWorkspacePackage { .. } => Some(Ecosystem::Cargo),
                        VersionWriteTarget::Manifest(path) => callisto_model::ManifestFormat::from_path(path)
                            .ok()
                            .map(|fmt| fmt.ecosystem()),
                    }
                }))
        })
        .chain(plan.rewrites.iter().filter_map(|rewrite| {
            match &rewrite.key.target {
                DepWriteTarget::CargoWorkspaceDependency { .. } => Some(Ecosystem::Cargo),
                DepWriteTarget::Manifest(path) => callisto_model::ManifestFormat::from_path(path)
                    .ok()
                    .map(|fmt| fmt.ecosystem()),
            }
        }))
        .chain(
            plan.platform_writes
                .iter()
                .filter_map(|write| callisto_model::ManifestFormat::from_path(&write.manifest).ok())
                .map(|fmt| fmt.ecosystem()),
        )
        .chain(
            plan.optional_dep_updates
                .iter()
                .filter_map(|update| callisto_model::ManifestFormat::from_path(&update.manifest).ok())
                .map(|fmt| fmt.ecosystem()),
        )
        .collect();

    // Must run before the git-staging loop below, so refreshed lockfiles are on disk to be staged.
    if opts.refresh_lockfiles {
        let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();

        if active_ecosystems.contains(&Ecosystem::Cargo) {
            refresh_results.push(run_lockfile_refresh(
                runner,
                root,
                "Cargo.lock",
                "cargo",
                &["update", "--workspace"],
            )?);
        }

        if active_ecosystems.contains(&Ecosystem::Pypi) {
            if root.join("uv.lock").exists() {
                refresh_results.push(run_lockfile_refresh(runner, root, "uv.lock", "uv", &["lock"])?);
            } else if root.join("poetry.lock").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "poetry.lock",
                    "poetry",
                    &["lock", "--no-update"],
                )?);
            } else if root.join("pdm.lock").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "pdm.lock",
                    "pdm",
                    &["lock", "--update-reuse"],
                )?);
            }
        }

        if active_ecosystems.contains(&Ecosystem::Npm) {
            if root.join("package-lock.json").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "package-lock.json",
                    "npm",
                    &["install", "--package-lock-only", "--ignore-scripts"],
                )?);
            }
            if root.join("pnpm-lock.yaml").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "pnpm-lock.yaml",
                    "pnpm",
                    &["install", "--lockfile-only"],
                )?);
            }
            if root.join("yarn.lock").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "yarn.lock",
                    "yarn",
                    &["install", "--mode", "update-lockfile"],
                )?);
            }
            if root.join("bun.lock").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "bun.lock",
                    "bun",
                    &["install", "--lockfile-only"],
                )?);
            } else if root.join("bun.lockb").exists() {
                refresh_results.push(run_lockfile_refresh(
                    runner,
                    root,
                    "bun.lockb",
                    "bun",
                    &["install", "--lockfile-only"],
                )?);
            }
        }

        if !refresh_results.is_empty() {
            outcome.lockfile_refresh_results = Some(refresh_results);
        }
    }

    // Map each well-known lockfile to its ecosystem, then include the file
    // only when that ecosystem is active and the file exists on disk.
    let lockfile_ecosystems: &[(&str, Ecosystem)] = &[
        ("Cargo.lock", Ecosystem::Cargo),
        ("package-lock.json", Ecosystem::Npm),
        ("pnpm-lock.yaml", Ecosystem::Npm),
        ("yarn.lock", Ecosystem::Npm),
            governed_by: Some(callisto_model::ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS),
        });
    }

    escalate(&mut diagnostics, opts.strict);

    let (pre_state_update, delete_pre_json) = if let Some(mut state) = pre_state {
        if state.mode == callisto_model::format::PreMode::Exit {
            (None, Some(ws.config.pre_json_path()))
        } else {
            // Records ids aggregate() determined are newly-seen this run; see Aggregation::new_pre_changesets.
            for id in &agg.new_pre_changesets {
                if !state.changesets.iter().any(|s| s == id) {
                    state.changesets.push(id.clone());
                }
            }
            (Some(state), None)
        }
    } else {
        (None, None)
    };

    let targets = bumps.iter().map(|b| (b.package.clone(), b.to.clone())).collect();
    let (platform_writes, optional_dep_updates) = platform_version_writes(ws, &targets)?;

    Ok(VersionPlan {
        bumps,
        rewrites: outcome.rewrites.into_values().collect(),
        platform_writes,
        optional_dep_updates,
        changelog_writes,
        consumed_changesets: agg.consumed,
        pre_state_update,
        pre_json_path: ws.config.pre_json_path(),
        pre_json_original_text,
        delete_pre_json,
        pre_cursor_updates: Vec::new(),
        observed_versions: base_versions,
        diagnostics,
    })
}

/// Refuses when the workspace shows the signature of a crashed `version` run: a manifest's on-disk version has
/// moved past `HEAD` while either a changeset is still pending there, or (outside an active pre-release cycle) the
/// manifest is staged but uncommitted. Continuing would compound the drift instead of surfacing it.
pub fn check_partial_run<R: CommandRunner, D: DependencyResolver>(ws: &Workspace<'_, R, D>) -> Result<(), GraphError> {
    let head = match ws.git_access().head_sha() {
        Ok(head) => head,
        Err(error) => {
            let output = ws
                .runner
                .run("git", &["rev-parse", "--verify", "--quiet", "HEAD"], &ws.root)
                .map_err(GraphError::Command)?;
            match output.exit_code {
                Some(1) => return Ok(()),
                Some(0) => return Err(error.into()),
                exit_code => {
                    return Err(GraphError::Command(callisto_model::CommandError::Failed {
                        program: "git".to_string(),
                        exit_code,
                        stderr: output.stderr,
                    }))
                }
            }
        }
    };
    let head = head.as_str();

    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
    let in_pre_release_cycle = ws.root.join(ws.config.pre_json_path()).exists();

    let pending = head_has_pending_changeset(ws, head)?
        || (!in_pre_release_cycle && any_canonical_manifest_staged_uncommitted(ws)?);
    if !pending {
        return Ok(());
    }

    let cargo_root = if ws
        .graph
        .packages()
        .flat_map(|pkg| pkg.canonical_manifests())
        .any(|decl| decl.ecosystem() == callisto_model::Ecosystem::Cargo)
    {
        manifest_blob_at(ws, head, "Cargo.toml")?
    } else {
        None
    };
    let base_versions = ws.base_versions()?;
    for pkg in ws.graph.packages() {
        let Some(disk) = base_versions.get(&pkg.id) else {
            continue;
        };
        for decl in pkg.canonical_manifests() {
            let path = super::release_decision::normalized_git_path(&decl.path)?;
            let Some(head_version) = manifest_version_at(ws, head, &path, cargo_root.as_deref())? else {
                continue;
            };
            if *disk != head_version.version {
                return Err(GraphError::PartialVersionRun {
                    path: head_version.authority,
                    disk: disk.clone(),
                    head: head_version.version,
                });
            }
        }
    }

    Ok(())
}

/// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
fn any_canonical_manifest_staged_uncommitted<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
) -> Result<bool, GraphError> {
    let mut paths = std::collections::BTreeSet::new();
    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
        paths.insert(super::release_decision::normalized_git_path(&decl.path)?);
        if decl.ecosystem() == callisto_model::Ecosystem::Cargo {
            paths.insert("Cargo.toml".to_string());
        }
    }
    for path in paths {
        let output = ws
            .runner
            .run("git", &["diff", "--cached", "--quiet", "--", &path], &ws.root)
            .map_err(GraphError::Command)?;
        match output.exit_code {
            Some(0) => {}
            Some(1) => return Ok(true),
            exit_code => {
                return Err(GraphError::Command(callisto_model::CommandError::Failed {
                    program: "git".to_string(),
                    exit_code,
                    stderr: output.stderr,
                }))
            }
        }
    }
    Ok(false)
}

/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    spec: &str,
) -> Result<bool, GraphError> {
    let output = ws
        .runner
        .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
        .map_err(GraphError::Command)?;
    match output.exit_code {
        Some(0) => Ok(true),
        Some(1) => Ok(false),
        exit_code => Err(GraphError::Command(callisto_model::CommandError::Failed {
            program: "git".to_string(),
            exit_code,
            stderr: output.stderr,
        })),
    }
}

