use std::path::Path;
use std::time::Duration;

/// The minimum `git` version callisto supports, as a [`semver::VersionReq`] grammar string
/// consumed directly by [`check_git_version`] — the single place this floor is defined, so
/// the requirement used for the actual comparison and the one rendered in
/// [`CommandError::IncompatibleVersion`]'s message can never drift apart.
pub const REQUIRED_GIT: &str = ">=2.20";

/// Trait for executing subprocess commands.
pub trait CommandRunner: Send + Sync {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError>;

    /// Run a command with a hard wall-clock timeout. If the process does not
    /// exit before `timeout` elapses it is killed and
    /// [`CommandError::TimedOut`] is returned.
    ///
    /// The default implementation ignores `timeout` and delegates to [`Self::run`].
    /// Implementors that control a real subprocess should override this with an
    /// actual deadline check.
    fn run_with_timeout(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        _timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        self.run(program, args, cwd)
    }

    /// Like [`Self::run_with_timeout`], but for an internal existence/probe
    /// check whose stderr looks like a failure on the common path (e.g.
    /// `npm view` against an unpublished package prints a 404-shaped "not
    /// found" to stderr normally) -- unlike a real, user-facing mutating
    /// command, this must not stream that noise live to the terminal, only
    /// capture it into [`CommandOutput`] for the caller to classify.
    ///
    /// Default implementation just delegates to [`Self::run_with_timeout`]
    /// (streams live); implementors doing their own live-streaming should
    /// override this to suppress it for probe calls.
    fn run_quiet(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        self.run_with_timeout(program, args, cwd, timeout)
    }

    /// Like [`Self::run`], but pipes `stdin` to the child process before
    /// reading its output. Needed for subcommands with a line-oriented
    /// input protocol -- e.g. `git cat-file --batch`, which reads one
    /// object identifier per line from stdin and streams each object's
    /// contents back on stdout, letting many objects be fetched in one
    /// subprocess round trip instead of one invocation per object.
    ///
    /// The default implementation returns [`CommandError::Unsupported`]:
    /// the great majority of [`CommandRunner`] implementors in this
    /// workspace (test doubles, etc.) never pipe
    /// stdin to a child process, so they don't need to implement this --
    /// only a real subprocess-backed runner used for such a call should
    /// override it.
    fn run_with_stdin(
        &self,
        program: &str,
        _args: &[&str],
        _cwd: &Path,
        _stdin: &[u8],
    ) -> Result<CommandOutput, CommandError> {
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this CommandRunner does not support piping input to the child process".to_string(),
        })
    }
}

/// Output from executing a command.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CommandOutput {
    pub exit_code: Option<i32>,
    pub stdout: String,
    pub stderr: String,
}

impl CommandOutput {
    pub fn success(&self) -> bool {
        self.exit_code == Some(0)
    }

    pub fn stdout_trimmed(&self) -> &str {
        self.stdout.trim()
    }

    pub fn stdout_lines(&self) -> impl Iterator<Item = &str> {
        self.stdout.lines().map(|l| l.trim()).filter(|l| !l.is_empty())
    }

    /// Redacts known registry/VCS credential env-var values and any URL
    /// userinfo component from this command's raw stderr before it's
    /// embedded in a caller's user-facing error -- a failing subprocess
    /// invocation can surface an authenticated remote URL (e.g. GitHub
    /// Actions' `REDACTED`) verbatim in
    /// its own error output, and that text flows into `--format json` and
    /// miette diagnostic output downstream.
    ///
    /// Delegates to [`crate::redact_command_stderr`], the single shared
    /// definition of how this workspace redacts subprocess stderr.
    pub fn redacted_stderr(&self) -> String {
        crate::registry::redact_command_stderr(&self.stderr)
    }
}

/// Errors occurring during command execution.
#[derive(Clone, Debug, thiserror::Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum CommandError {
    #[error("`{program}` was not found; callisto requires it to be available")]
    #[diagnostic(code(E020), help("Ensure program is installed and available on system PATH."))]
    NotFound { program: String },

    #[error("`{program}` reports version `{found}`, but callisto requires {required}")]
    #[diagnostic(code(E021), help("Upgrade program to meet version requirement."))]
    IncompatibleVersion {
        program: String,
        found: String,
        required: String,
    },

    #[error("executing `{program}` is not supported on this surface: {reason}")]
    #[diagnostic(code(E022), help("Run this command on a surface where `{program}` can be executed."))]
    Unsupported { program: String, reason: String },

    #[error("`{program}` failed with exit code {exit_code:?}: {stderr}")]
    #[diagnostic(code(E023), help("Inspect the reported stderr to diagnose why `{program}` failed."))]
    Failed {
        program: String,
        exit_code: Option<i32>,
        stderr: String,
    },
/// already-detected `package_manager` (see [`detect_npm_package_manager`]).
///
/// | Package manager | Program | Base args                                  |
/// |------------------|---------|--------------------------------------------|
/// | Pnpm             | `pnpm`  | `publish --filter=<name> --no-git-checks`  |
/// | Yarn             | `yarn`  | `workspace <name> npm publish`             |
/// | Bun              | `bun`   | `publish` (run from `package_dir`)         |
/// | Npm              | `npm`   | `publish --workspace=<name>`               |
///
/// `--filter=`/`--workspace=` use the joined form so the name cannot be
/// re-read as an option. Yarn takes the name positionally and has no joined
/// spelling, so there it rests on `ReleasePackageId`'s leading-`-` rejection.
///
/// `tag`/`access`/`registry` are appended to every variant's base args.
/// `package_dir` is only used for bun: it has no `--filter`/`--workspace`
/// flag to target one package by name, so it alone must run from the
/// package's own directory rather than the workspace root.
pub fn npm_publish_argv(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    package_manager: NpmPackageManager,
    tag: Option<&str>,
    access: Option<NpmAccess>,
    registry: Option<&str>,
) -> Argv {
    let extra = npm_publish_flags(package_name, tag, access, registry);

    let (program, mut args, cwd) = match package_manager {
        NpmPackageManager::Pnpm => (
            "pnpm",
            vec![
                "publish".to_string(),
                // `--filter=<name>`, not `--filter <name>`: the joined form
                // cannot be re-read as an option even if a name slipped past
                // `ReleasePackageId`'s charset rule.
                format!("--filter={package_name}"),
                // pnpm >= 7 refuses to publish from a dirty working tree by
                // default. After `callisto version` stages manifest bumps,
                // the tree is always dirty until the operator commits, so
                // this bypasses the git-status check.
                "--no-git-checks".to_string(),
            ],
            workspace_root.to_path_buf(),
        ),
        NpmPackageManager::Yarn => (
            "yarn",
            vec![
                "workspace".to_string(),
                package_name.to_string(),
                "npm".to_string(),
                "publish".to_string(),
            ],
            workspace_root.to_path_buf(),
        ),
        NpmPackageManager::Bun => ("bun", vec!["publish".to_string()], workspace_root.join(package_dir)),
        NpmPackageManager::Npm => (
            "npm",
            vec!["publish".to_string(), format!("--workspace={package_name}")],
            workspace_root.to_path_buf(),
        ),
    };
    args.extend(extra);
    Argv {
        program: program.to_string(),
        args,
        cwd,
    }
}

/// The access an npm package publishes with: the explicit `publishConfig.access`,
/// else `public` for a scoped `@scope/name` (npm defaults scoped packages to restricted).
pub fn npm_default_access(name: &str, explicit: Option<NpmAccess>) -> Option<NpmAccess> {
    explicit.or_else(|| name.starts_with('@').then_some(NpmAccess::Public))
}

/// `--tag`/`--access`/`--registry`, shared by every npm-ecosystem publish argv.
fn npm_publish_flags(
    package_name: &str,
    tag: Option<&str>,
    access: Option<NpmAccess>,
        &self,
        context: &ProviderContext<'_>,
        operation: &RegistryPublishOperation,
    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
        let url = pypi_simple_index_url(operation.registry.endpoint.as_deref(), &operation.package_name);
        let accept_header = format!("Accept: {PYPI_SIMPLE_ACCEPT}");
        let args = ["-sS", "-i", "-H", accept_header.as_str(), url.as_str()];
        let output = match run_observation(
            context.runner(),
            programs::CURL,
            &args,
            context.root(),
            timeouts::REGISTRY_QUERY,
            false,
        )? {
            Ok(output) => output,
            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
        };
        Ok(classify_pypi_simple(&output, &operation.version))
    }

    fn publish(
        &self,
        context: &ProviderContext<'_>,
        operation: &RegistryPublishOperation,
    ) -> Result<CommandOutput, GraphError> {
        let steps = registry_argv::pypi_publish_argv(
            context.root(),
            &operation.package_dir,
            &operation.package_name,
            &operation.version,
            operation.registry.endpoint.as_deref(),
        )?;
        let [build, upload] = steps.as_slice() else {
            return Err(GraphError::ReleaseInvariant {
                detail: "pypi_publish_argv did not return exactly a build and an upload step".to_string(),
            });
        };
        let built = run_argv(context, build)?;
        if built.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: build.program.clone(),
                args: build.args.clone(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: built.exit_code,
                    stderr: built.stderr,
                },
            });
        }
        run_argv(context, upload)
    }

    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
        registry_argv::classify_twine_output(output)
    }
}

/// The plan-time gate: an ecosystem whose client cannot prove a version absent
/// could never mint the absence proof an effect needs, nor the exact evidence a
/// receipt needs, so the plan is refused here rather than at dispatch.
pub(crate) fn require_observable_registry(ecosystem: Ecosystem) -> Result<(), GraphError> {
    if !adapter_for(ecosystem)?.can_observe_versions() {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::ObservableRegistryClient,
        });
    }
    Ok(())
}

