    /// Rejects any post-decision forge state change before the executor mutates.
    pub fn verify_snapshot(&self, observed: &ReleasePrSnapshotV2) -> Result<(), ReleasePrDecisionError> {
        if observed != &self.snapshot {
            return Err(ReleasePrDecisionError::SnapshotChanged);
        }
        Ok(())
    }

    /// Allows only the selected PR head change performed by this executor.
    pub fn verify_snapshot_after_update(
        &self,
        observed: &ReleasePrSnapshotV2,
        applied_head: &CommitSha,
    ) -> Result<(), ReleasePrDecisionError> {
        let ReleasePrActionV2::Update {
            pull_request_number, ..
        } = &self.action
        else {
            return Err(ReleasePrDecisionError::SnapshotChanged);
        };
        if Self::derive(true, &self.config, &self.snapshot)?.action != self.action {
            return Err(ReleasePrDecisionError::SnapshotChanged);
        }
        let mut expected = self.clone();
        let pr = expected
            .snapshot
            .open_pull_requests
            .iter_mut()
            .find(|pr| pr.number == *pull_request_number)
            .ok_or(ReleasePrDecisionError::SnapshotChanged)?;
        pr.head_commit = applied_head.clone();
        expected.verify_snapshot(observed)
    }
}

/// The on-the-wire shape of [`ReleasePrDecisionV2`], with its nested config and
/// snapshot still unvalidated. See [`ReleasePrConfigWireV1`] for why the CLI
/// deserializes this instead of `ReleasePrDecisionV2` directly.
#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleasePrDecisionWireV2 {
    pub schema_version: u8,
    pub config: ReleasePrConfigWireV1,
    pub snapshot: ReleasePrSnapshotWireV2,
    pub action: ReleasePrActionV2,
}

impl ReleasePrDecisionV2 {
    /// Validates an already-parsed wire value, including its nested config and snapshot,
    /// into a well-formed decision.
    pub fn from_wire(wire: ReleasePrDecisionWireV2) -> Result<Self, ReleasePrDecisionError> {
        check_schema_version(wire.schema_version, Self::SCHEMA_VERSION, "release PR decision")?;
        Ok(Self {
            schema_version: wire.schema_version,
            config: ReleasePrConfigV1::from_wire(wire.config)?,
                .map_err(GraphError::Command)?;
            match output.exit_code {
                Some(1) => return Ok(()),
                Some(0) => return Err(error.into()),
                exit_code => {
                    return Err(GraphError::Command(callisto_model::CommandError::Failed {
                        program: "git".to_string(),
                        exit_code,
                        stderr: output.stderr,
                    }))
                }
            }
        }
    };
    let head = head.as_str();

    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
    let in_pre_release_cycle = ws.root.join(ws.config.pre_json_path()).exists();

    let staged_manifests = if in_pre_release_cycle {
        BTreeSet::new()
    } else {
        canonical_manifest_staged_paths(ws)?
    };
    let pending = !in_pre_release_cycle
        && (head_has_pending_changeset(ws, head)?
            || working_tree_has_pending_changeset(ws)?
            || !staged_manifests.is_empty());
    if !pending {
        return Ok(());
    }

    let cargo_root = if ws
        .graph
        .packages()
        .flat_map(|pkg| pkg.canonical_manifests())
        .any(|decl| decl.ecosystem() == callisto_model::Ecosystem::Cargo)
    {
        manifest_blob_at(ws, head, "Cargo.toml")?
    } else {
        None
    };
    let cargo_root_index = if staged_manifests.contains("Cargo.toml") {
        manifest_blob_in_index(ws, "Cargo.toml")?
    } else {
        None
    };
    let base_versions = ws.base_versions()?;
    for pkg in ws.graph.packages() {
        let Some(disk) = base_versions.get(&pkg.id) else {
            continue;
        };
        for decl in pkg.canonical_manifests() {
            let path = super::release_decision::normalized_git_path(&decl.path)?;
            let Some(head_version) = manifest_version_at(ws, head, &path, cargo_root.as_deref())? else {
                continue;
            };
            let index_path_changed = staged_manifests.contains(&path)
                || (decl.ecosystem() == callisto_model::Ecosystem::Cargo && staged_manifests.contains("Cargo.toml"));
            let index_version = if index_path_changed {
                manifest_version_in_index(ws, &path, cargo_root_index.as_deref())?
            } else {
                None
            };
            let index_display = match &index_version {
                Some(version) => version.version.render().to_string(),
                None if index_path_changed => "absent".to_string(),
                None => head_version.version.render().to_string(),
            };
            let index_differs = index_path_changed
                && index_version
                    .as_ref()
                    .is_none_or(|version| version.version != head_version.version);
            if *disk != head_version.version || index_differs {
                return Err(GraphError::PartialVersionRun {
                    path: head_version.authority,
                    disk: disk.clone(),
                    index: index_display,
                    head: head_version.version,
                });
            }
        }
    }

    Ok(())
}
