            if !output.success() {
                return Err(GraphError::Command(CommandError::Failed {
                    program: "git".to_string(),
                    exit_code: output.exit_code,
                    stderr: output.redacted_stderr(),
                }));
            }
        }

        if !deleted.is_empty() {
            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
            let strs: Vec<String> = deleted.iter().map(|p| p.display().to_string()).collect();
            for s in &strs {
                args.push(s);
            }
            let output = runner.run("git", &args, root)?;
            if !output.success() {
                return Err(GraphError::Command(CommandError::Failed {
                    program: "git".to_string(),
                    exit_code: output.exit_code,
                    stderr: output.redacted_stderr(),
                }));
            }
        }

        if !deferred_deletions.is_empty() {
            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
            let strs: Vec<String> = deferred_deletions.iter().map(|p| p.display().to_string()).collect();
            for s in &strs {
                args.push(s);
            }
            let output = runner.run("git", &args, root)?;
            if !output.success() {
                return Err(GraphError::Command(CommandError::Failed {
                    program: "git".to_string(),
                    exit_code: output.exit_code,
                    stderr: output.redacted_stderr(),
                }));
            }

            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
            for path in &deferred_deletions {
                let full = root.join(path);
                if full.exists() {
                    fs::remove_file(&full).map_err(|e| GraphError::ApplyIo {
                        path: path.clone(),
                        message: e.to_string(),
                    })?;
                }
            }
            modified_paths.extend(deferred_deletions.iter().cloned());
        }

        outcome.staged = modified_paths;
    }

    Ok(outcome)
}

/// Maps a non-zero exit to `GraphError::LockfileRefreshFailed`, an exec failure to `GraphError::Command`.
fn run_lockfile_refresh<R: CommandRunner>(
    runner: &R,
    root: &Path,
    filename: &str,
    program: &str,
    args: &[&str],
) -> Result<LockfileRefreshResult, GraphError> {
    let refresh_command = format!("{program} {}", args.join(" "));
    let out = runner.run(program, args, root)?;
    if !out.success() {
        return Err(GraphError::LockfileRefreshFailed {
            filename: PathBuf::from(filename),
            refresh_command,
            // Records ids aggregate() determined are newly-seen this run; see Aggregation::new_pre_changesets.
            for id in &agg.new_pre_changesets {
                if !state.changesets.iter().any(|s| s == id) {
                    state.changesets.push(id.clone());
                }
            }
            (Some(state), None)
        }
    } else {
        (None, None)
    };

    let targets = bumps.iter().map(|b| (b.package.clone(), b.to.clone())).collect();
    let (platform_writes, optional_dep_updates) = platform_version_writes(ws, &targets)?;

    Ok(VersionPlan {
        bumps,
        rewrites: outcome.rewrites.into_values().collect(),
        platform_writes,
        optional_dep_updates,
        changelog_writes,
        consumed_changesets: agg.consumed,
        pre_state_update,
        pre_json_path: ws.config.pre_json_path(),
        pre_json_original_text,
        delete_pre_json,
        pre_cursor_updates: Vec::new(),
        observed_versions: base_versions,
        diagnostics,
    })
}

