#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub(crate) enum ParsedVersionReq {
    SemVer(semver::VersionReq),
    Pep440(pep440_rs::VersionSpecifiers),
}

/// Parsed version requirement.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VersionReq {
    grammar: VersionGrammar,
    ecosystem: Ecosystem,
    req: ParsedVersionReq,
    raw: String,
}

string_json_schema!(VersionReq);

impl VersionReq {
    pub fn parse(raw: &str, ecosystem: Ecosystem) -> Result<Self, VersionParseError> {
        let grammar = ecosystem.version_grammar();
        match grammar {
            VersionGrammar::SemVer => {
                let req = semver::VersionReq::parse(raw).map_err(|e| VersionParseError {
                    raw: raw.to_string(),
                    grammar,
                    message: e.to_string(),
                })?;
                Ok(VersionReq {
                    grammar,
                    ecosystem,
                    req: ParsedVersionReq::SemVer(req),
                    raw: raw.to_string(),
                })
            }
            VersionGrammar::Pep440 => {
                let req = raw
                    .parse::<pep440_rs::VersionSpecifiers>()
                    .map_err(|e| VersionParseError {
                        raw: raw.to_string(),
                        grammar,
                        message: e.to_string(),
                    })?;
                // Normalize raw to pep440_rs's canonical rendering so that
                // logically-equal specifiers (e.g. ">=1.0.0A1" vs ">=1.0.0a1")
                // produce identical raw values and therefore compare == and hash
                // equal (derived PartialEq/Eq/Hash include raw).
                let canonical = req.to_string();
                Ok(VersionReq {
                    grammar,
                    ecosystem,
                    req: ParsedVersionReq::Pep440(req),
                    raw: canonical,
                })
            }
            VersionGrammar::Maven => Err(VersionParseError {
                raw: raw.to_string(),
                grammar,
                message: format!("{grammar:?} version requirements not implemented"),
            }),
        }
    }


fn parse_npm_spec_str(s: &str, ws_kind: Option<WorkspaceKind>) -> DepSpec {
    if let Some(rest) = s.strip_prefix("workspace:") {
        if let Some(kind) = ws_kind {
            return DepSpec::WorkspaceProtocol(WorkspaceSpec {
                kind,
                suffix: rest.to_string(),
            });
        }
        return DepSpec::Opaque(format!("workspace:{rest}"));
    }
    if let Some(rest) = s.strip_prefix("catalog:") {
        let name = if rest.is_empty() { None } else { Some(rest.to_string()) };
        return DepSpec::Catalog(name);
    }

    if crate::common::is_bare_semver(s) {
        if let Ok(v) = Version::parse(s, VersionGrammar::SemVer) {
            return DepSpec::Exact(v);
        }
    }

    if let Ok(req) = VersionReq::parse(s, Ecosystem::Npm) {
        return DepSpec::Range(req, s.to_string());
    }

    DepSpec::Opaque(s.to_string())
}

pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
    match spec {
        DepSpec::WorkspaceProtocol(workspace) => {
            if workspace.coverage(target).ok()? != callisto_model::Coverage::DoesNotCover {
                return None;
            }
            let range = workspace.range()?;
            let rewritten = if Version::parse(range, VersionGrammar::SemVer).is_ok() {
                target.render().to_string()
            } else {
                let req = VersionReq::parse(range, Ecosystem::Npm).ok()?;
                round_trip(&DepSpec::Range(req, range.to_string()), target)?.render()
            };
            let updated = workspace.with_range(&rewritten);
            if updated.coverage(target).ok()? != callisto_model::Coverage::Covers {
                return None;
            }
            Some(DepSpec::WorkspaceProtocol(updated))
        }
        DepSpec::Exact(_) => Some(DepSpec::Exact(target.clone())),
        DepSpec::Range(_, original) => {
            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
            if rest.contains(' ') || rest.contains('-') || rest.contains('|') || rest.contains(['x', 'X', '*']) {
                return None;
            }
            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
            let req = VersionReq::parse(&rendered, Ecosystem::Npm).ok()?;
            Some(DepSpec::Range(req, rendered))
        }
        _ => None,
    }
}

fn render_at_precision(target: &Version, original_clause: &str) -> String {
